const wait = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms));

async function main() {
  const finished = [];
  const track = (p) => p.then((v) => { finished.push(v); return v; });
  const results = await Promise.all([track(wait(30, "canteen")), track(wait(10, "library")), track(wait(20, "hostel"))]);
  console.log("finished in:", finished.join(", "));
  console.log("Promise.all gives:", results.join(", "));
  try {
    await Promise.all([wait(5, "ok"), Promise.reject(new Error("hostel API down"))]);
  } catch (e) {
    console.log("Promise.all rejected:", e.message);
  }
  const settled = await Promise.allSettled([wait(5, "ok"), Promise.reject(new Error("down"))]);
  console.log("allSettled:", settled.map((s) => s.status).join(", "));
}

main();

