const wait = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms));

// Pretend each office answers after `ms` milliseconds with its seat count.
function fetchSeats(office, ms, seats) {
  return wait(ms, `${office}: ${seats}`);
}

async function main() {
  const n = Number(lines[0]);
  const jobs = [];
  for (let k = 1; k <= n; k++) {
    const [office, ms, seats] = lines[k].split(" ");
    jobs.push(fetchSeats(office, Number(ms), seats));
  }
  // TODO: print the answers in INPUT order. This prints them as they arrive.
  for (const job of jobs) job.then((answer) => console.log(answer));
}

main();

